const items = $input.all();
  const storeFiles = $('StoreFile').all();
  const results = [];

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const storeItem = storeFiles[i];

    if (item.json.error) {
      results.push({
        json: {
          isValid: false,
          validationError: 'Gemini extraction failed',
          messageId: storeItem ? storeItem.json.messageID : null,
          source: storeItem ? storeItem.json.source : null
        },
        pairedItem: i
      });
      continue;
    }

    let response = item.json.content?.parts?.[0]?.text || item.json.text || '';
    response = response.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

    try {
      const data = JSON.parse(response);

      const isValid =
        (data.customer_tax_id === null || data.customer_tax_id?.length >= 10) &&
        data.customer_company?.length > 0 &&
        data.invoice_issued_date?.match(/\d{4}-\d{2}-\d{2}/) &&
        data.invoice_number?.length > 0 &&
        data.invoice_amount_gross !== undefined &&
        data.currency?.length >= 3 &&
        data.category?.length > 0;

      results.push({
        json: {
          ...data,
          isValid: isValid,
          validationError: isValid ? null : 'Missing or invalid required fields',
          messageId: storeItem ? storeItem.json.messageID : null,
          source: storeItem ? storeItem.json.source : null
        },
        binary: storeItem ? storeItem.binary : {},
        pairedItem: i
      });

    } catch (e) {
      results.push({
        json: {
          isValid: false,
          validationError: 'JSON parse failed: ' + e.message,
          rawResponse: response.substring(0, 200),
          messageId: storeItem ? storeItem.json.messageID : null,
          source: storeItem ? storeItem.json.source : null
        },
        pairedItem: i
      });
    }
  }

  return results;

const folders = $input.all();
const invoiceData = $('Validate Data').first().json;
const invoiceBinary = $('Validate Data').first().binary || {};

const invoiceMonth = invoiceData['invoice_issued_month-pl'];
const matchingFolder = folders.find(folder => folder.json.name === invoiceMonth);

const parentFolderId = folders.length > 0 ? folders[0].json.parentReference?.id : null;

const dateCompact = (invoiceData.invoice_issued_date || '').replace(/-/g, '');
const category = (invoiceData.category || 'unknown').toLowerCase();
const invNum = (invoiceData.invoice_number || '').replace(/[^a-zA-Z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 30);
const fileName = `${dateCompact}-${category}-${invNum}.pdf`;

const binaryKeys = Object.keys(invoiceBinary);
const binaryKey = binaryKeys.find(k => k === 'currentFile') || binaryKeys[0];
const binaryData = binaryKey ? invoiceBinary[binaryKey] : null;
const renamedBinary = binaryData ? { currentFile: { ...binaryData, fileName } } : {};

const baseJson = {
  folderName: invoiceMonth,
  fileName,
  parentFolderId,
  needsCreation: !matchingFolder,
  messageID: invoiceData.messageId,
  source: invoiceData.source,
  supplier_company: invoiceData.supplier_company,
  customer_tax_id: invoiceData.customer_tax_id,
  customer_company: invoiceData.customer_company,
  invoice_number: invoiceData.invoice_number,
  invoice_issued_date: invoiceData.invoice_issued_date,
  invoice_amount_net: invoiceData.invoice_amount_net,
  invoice_amount_tax: invoiceData.invoice_amount_tax,
  invoice_amount_gross: invoiceData.invoice_amount_gross,
  currency: invoiceData.currency,
  category: invoiceData.category,
};

if (matchingFolder) {
  baseJson.folderId = matchingFolder.json.id;
  baseJson.folderPath = matchingFolder.json.webUrl;
}

return [{ json: baseJson, binary: renamedBinary }];

