const items = $input.all();

const byMessage = new Map();
for (const item of items) {
  const key = item.json.parentMessageId;
  if (!byMessage.has(key)) byMessage.set(key, []);
  byMessage.get(key).push(item);
}

const out = [];
for (const attachments of byMessage.values()) {
  if (attachments.length === 1) {
    out.push(attachments[0]);
    continue;
  }

  const hasReceipt = attachments.some(a => /receipt/i.test(a.json.name || ''));
  const hasInvoice = attachments.some(a => /invoice/i.test(a.json.name || ''));

  if (hasReceipt && hasInvoice) {
    const invoice = attachments.find(a => /invoice/i.test(a.json.name || ''));
    out.push(invoice);
  } else {
    out.push(...attachments);
  }
}

return out;

const created = $input.first().json;
const prior = $('SelectJDGFolder').first();
// If create succeeded, use the new folder id; if 409 (already exists), find it from existing folders
let folderId = created.id;
let folderPath = created.webUrl;
if (!folderId) {
  const existing = $('Get Months Folders JDG').all().find(f => f.json.name === prior.json.folderName);
