const bin = $input.item.binary || {};
const msgId = $json.id;

const pdfKeys = Object.keys(bin).filter(k =>
  k.startsWith('attachment_') &&
  (bin[k].mimeType === 'application/pdf' || /\.pdf$/i.test(bin[k].fileName || ''))
);

if (pdfKeys.length === 0) {
  return { json: { messageID: msgId, source: 'gmail', skip: true }, binary: {} };
}

const isInvoice = k => /invoice|faktura/i.test(bin[k].fileName || '');
const isReceipt = k => /receipt|paragon/i.test(bin[k].fileName || '');
let chosen = pdfKeys[0];
if (pdfKeys.length > 1 && pdfKeys.some(isInvoice) && pdfKeys.some(isReceipt)) {
  chosen = pdfKeys.find(isInvoice);
}

return {
  json: { messageID: msgId, source: 'gmail' },
  binary: { data: bin[chosen] }
};

const html = $json.html || '';
const text = $json.text || '';
const body = html + ' ' + text;
const all = body.match(/https?:\/\/[^\s<>"')]+/gi) || [];
// Only keep links that look like a downloadable PDF / invoice document,
// not every tracking pixel or stylesheet URL in the email.
const pdfLinks = all.filter(u =>
  /\.pdf(\?|$)/i.test(u) ||
  /\/pdf(\?|$)/i.test(u) ||
  /files\.stripe\.com/i.test(u) ||
  /receipts?\/invoices?/i.test(u)
);
const links = [...new Set(pdfLinks)];
return { json: { messageID: $json.id, source: 'gmail', links } };

